let galleryFilter='all',galleryLimit=6;
const galleryItems=[...document.querySelectorAll('.gallery-item')],more=document.querySelector('#view-more');
function renderGallery(){const matching=galleryItems.filter(item=>galleryFilter==='all'||item.dataset.category===galleryFilter);galleryItems.forEach(item=>{item.hidden=!matching.includes(item)||matching.indexOf(item)>=galleryLimit;});more.hidden=matching.length<=galleryLimit;document.querySelector('#gallery-count').textContent=`${Math.min(galleryLimit,matching.length)} of ${matching.length} looks`;}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{galleryFilter=button.dataset.filter;galleryLimit=6;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderGallery();}));
more.onclick=()=>{const visible=galleryItems.filter(item=>!item.hidden);galleryLimit+=6;renderGallery();const newlyVisible=galleryItems.find(item=>!item.hidden&&!visible.includes(item));newlyVisible?.focus({preventScroll:true});};renderGallery();
const panel=document.querySelector('#menu-panel');let menus=null,selectedMenu='nails';
const money=value=>typeof value==='number'?'₦'+value.toLocaleString('en-NG'):value;
function chooseMenu(key){selectedMenu=key;document.querySelectorAll('[data-menu]').forEach(tab=>{const active=tab.dataset.menu===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});panel.setAttribute('aria-labelledby','tab-'+key);if(!menus)return;const menu=menus[key];panel.replaceChildren();const heading=document.createElement('h3');heading.className='menu-title';heading.textContent=menu.title;const intro=document.createElement('p');intro.className='menu-intro';intro.textContent=menu.intro;panel.append(heading,intro);menu.groups.forEach(([group,description,items],index)=>{const details=document.createElement('details');details.className='price-group';details.open=index===0;const summary=document.createElement('summary');const name=document.createElement('span');name.textContent=group;const preview=document.createElement('small');const prices=items.map(item=>item[1]).filter(value=>typeof value==='number');preview.textContent=prices.length?'from '+money(Math.min(...prices)):'Let’s talk';summary.append(name,preview);details.append(summary);const text=document.createElement('p');text.className='group-intro';text.textContent=description;details.append(text);items.forEach(([service,price])=>{const row=document.createElement('div');row.className='price-row';const label=document.createElement('span');label.textContent=service;const cost=document.createElement('strong');cost.textContent=money(price);const button=document.createElement('button');button.type='button';button.className='price-book';button.textContent='Select ↗';button.setAttribute('aria-label',`Select ${service}, ${money(price)}`);button.onclick=()=>{document.querySelector('#service').value=key==='nails'?'Nails':key==='piercings'?'Piercing':'Semi-permanent tattoo';document.querySelector('#notes').value=`I'd like to book ${group} — ${service} (${money(price)}${group==='Nail art & extras'?', extra charge':''}).`;document.querySelector('#book').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#name').focus({preventScroll:true});};row.append(label,cost,button);details.append(row);});panel.append(details);});}
document.querySelectorAll('[data-menu]').forEach(tab=>{tab.onclick=()=>chooseMenu(tab.dataset.menu);tab.onkeydown=event=>{const tabs=[...document.querySelectorAll('[data-menu]')];let index=tabs.indexOf(tab);if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tabs[index].focus();chooseMenu(tabs[index].dataset.menu);};});
document.querySelectorAll('[data-price-menu]').forEach(link=>link.onclick=()=>chooseMenu(link.dataset.priceMenu));
fetch('price-menu.json').then(response=>{if(!response.ok)throw new Error();return response.json();}).then(data=>{menus=data;chooseMenu(selectedMenu);}).catch(()=>{panel.textContent='The price menu could not load. Please refresh or contact us on WhatsApp for current prices.';});
